{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Altiratinib, a structurally related pyridine-carboxamide diaryl ether kinase inhibitor, achieved a brain:plasma ratio of 0.23 in mice after systemic dosing, demonstrating significant CNS penetration despite similar polar aromatic features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A small-animal PET study in rats confirmed that a related heteroaryl compound is highly CNS penetrant and fast clearing, directly supporting meaningful brain access for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "ADX71441 showed CSF/plasma ratios of 0.042-0.062, comparable to its unbound plasma fraction of 0.085, indicating free passage across the BBB and supporting that moderate total CSF/plasma ratios can still reflect adequate CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "GNE-7915 achieved high CNS penetration in non-human primates (CSF/Pu AUC 0.8; Cub/Cup 0.69) and rats (CSF/plasma unbound 0.6), showing that kinase inhibitors with similar physicochemical properties can achieve robust brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "CNP520 distributed into human CSF with a CSF/plasma ratio equal to its unbound plasma fraction, demonstrating that low total CSF/plasma ratios can still represent meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Poziotinib showed excellent brain permeability in mice, with brain concentrations remaining above its IC50 for hours after dosing, supporting meaningful CNS exposure for a lipophilic multikinase inhibitor.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The high-transfer experimental evidence consistently indicates meaningful CNS access for structurally related kinase inhibitors, with direct brain/plasma, CSF/plasma, PET, and brain concentration measurements. Although the query's diaryl urea and high lipophilicity are potential efflux liabilities, the direct CNS exposure data from close analogues outweigh the physicochemical prior; under brain tumor/glioma conditions, BBB disruption further favors drug entry. Prediction: pass.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query molecule.",
    "No experimental efflux-transporter data for the query itself.",
    "Most evidence comes from intact-BBB models rather than brain tumor/glioma models.",
    "Unbound brain concentrations relative to target potency were not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

